update public.products set description='Prepared cow skin, locally known as Ponmo, with a characteristic chewy texture commonly used in Nigerian soups, stews, peppered dishes and assorted-meat preparations.', handling_protocols=array['Keep Ponmo refrigerated or frozen after delivery rather than leaving it soaking at room temperature.','If additional cleaning is needed, use clean potable water and minimise splashing onto nearby foods and surfaces.','Cook thoroughly before eating.']::text[], storage_tips=array['Refrigerate at 4°C or below and use within about 1–2 days.','For longer storage, freeze at about -18°C or below and use within about 2–3 months for best quality.','Do not leave prepared Ponmo soaking in water at room temperature.']::text[] where name='Ponmo' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
